package com.acme.db

import java.sql.{Connection, DriverManager, PreparedStatement, ResultSet}
import java.nio.charset.StandardCharsets
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

object RoleConstants {
  val ADMIN = "admin"
  val READER = "reader"
  val WRITER = "writer"
  val VALID_ROLES: Set[String] = Set(ADMIN, READER, WRITER)
}

case class SessionContext(userId: String, role: String, connString: String)

trait ConnectionStringBuilder {
  def buildConnString(host: String, port: Int, database: String, props: Map[String, String]): String
}

class PostgresConnStringBuilder extends ConnectionStringBuilder {

  private def encodePropertyValue(value: String): String = {
    // Encode special characters for JDBC connection string properties
    value.replace("\\", "\\\\").replace("=", "\\=")
  }

  private def sanitizePropertyKey(key: String): String = {
    key.replaceAll("[^a-zA-Z0-9_]", "")
  }

  override def buildConnString(host: String, port: Int, database: String, props: Map[String, String]): String = {
    val baseUrl = s"jdbc:postgresql://${host}:${port}/${database}"
    if (props.isEmpty) baseUrl
    else {
      val propString = props.map { case (k, v) =>
        s"${sanitizePropertyKey(k)}=${encodePropertyValue(v)}"
      }.mkString("&")
      s"${baseUrl}?${propString}"
    }
  }
}

class RoleBasedAccessController {

  private def computeHmac(data: String, secret: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256")
    mac.init(keySpec)
    val bytes = mac.doFinal(data.getBytes(StandardCharsets.UTF_8))
    bytes.map("%02x".format(_)).mkString
  }

  def validateRole(role: String): Boolean = {
    RoleConstants.VALID_ROLES.contains(role.trim.toLowerCase)
  }

  def authorizeQuery(ctx: SessionContext, query: String): Boolean = {
    ctx.role.toLowerCase match {
      case RoleConstants.ADMIN => true
      case RoleConstants.WRITER => !query.trim.toUpperCase.startsWith("DROP") && 
                                    !query.trim.toUpperCase.startsWith("ALTER")
      case RoleConstants.READER => query.trim.toUpperCase.startsWith("SELECT")
      case _ => false
    }
  }
}

class AuditLogger {

  def logQueryExecution(ctx: SessionContext, query: String, success: Boolean): Unit = {
    val sanitizedQuery = query.replace("\n", " ").replace("\r", " ")
    val logEntry = s"[AUDIT] user=${ctx.userId} role=${ctx.role} success=${success} query=${sanitizedQuery}"
    System.err.println(logEntry)
  }
}

class DatabaseDriver(
  connBuilder: ConnectionStringBuilder,
  accessController: RoleBasedAccessController,
  auditLogger: AuditLogger
) {

  private var connectionPool: Map[String, Connection] = Map.empty

  def createSession(userId: String, role: String, host: String, port: Int, 
                    database: String, applicationName: String): Either[String, SessionContext] = {
    if (!accessController.validateRole(role)) {
      return Left(s"Invalid role: ${role}")
    }

    // Build connection properties including application_name for tracking
    val props = Map(
      "application_name" -> buildApplicationIdentifier(userId, role, applicationName),
      "connect_timeout" -> "10",
      "ssl" -> "true"
    )

    val connString = connBuilder.buildConnString(host, port, database, props)
    Right(SessionContext(userId, role, connString))
  }

  private def buildApplicationIdentifier(userId: String, role: String, appName: String): String = {
    // Construct a descriptive application name for connection tracking
    // Format: appName/userId/role
    val normalizedAppName = normalizeIdentifier(appName)
    val normalizedUserId = normalizeIdentifier(userId)
    s"${normalizedAppName}/${normalizedUserId}/${role}"
  }

  private def normalizeIdentifier(input: String): String = {
    // Remove null bytes and limit length for safety
    val cleaned = input.replace("\u0000", "")
    if (cleaned.length > 64) cleaned.substring(0, 64) else cleaned
  }

  def executeQuery(ctx: SessionContext, query: String): Either[String, String] = {
    if (!accessController.authorizeQuery(ctx, query)) {
      auditLogger.logQueryExecution(ctx, query, success = false)
      return Left("Access denied for this query type")
    }

    try {
      val conn = getOrCreateConnection(ctx)
      val stmt = conn.prepareStatement(query)
      val rs = stmt.executeQuery()
      val result = extractResults(rs)
      auditLogger.logQueryExecution(ctx, query, success = true)
      Right(result)
    } catch {
      case e: Exception =>
        auditLogger.logQueryExecution(ctx, query, success = false)
        Left(s"Query execution failed: ${e.getMessage}")
    }
  }

  private def getOrCreateConnection(ctx: SessionContext): Connection = {
    connectionPool.getOrElse(ctx.connString, {
      val conn = DriverManager.getConnection(ctx.connString)
      connectionPool = connectionPool + (ctx.connString -> conn)
      conn
    })
  }

  private def extractResults(rs: ResultSet): String = {
    val meta = rs.getMetaData
    val colCount = meta.getColumnCount
    val sb = new StringBuilder
    while (rs.next()) {
      for (i <- 1 to colCount) {
        if (i > 1) sb.append(",")
        sb.append(rs.getString(i))
      }
      sb.append("\n")
    }
    sb.toString()
  }
}
